//! The editor's own PHP stubs (`data/php.stubs`, generated by `cargo xtask php-stubs` from every
//! PHP version via reflection): what PHP itself provides — functions with their
//! signatures, classes, methods, constants — and the version each appeared in (and was
//! removed in). Embedded in the binary; parsed on first use into indexes that point into
//! the embedded text (nothing is copied).

use std::collections::HashMap;

static DATA: &str = include_str!("../data/php.stubs");

/// The extensions every PHP build has (they can't be disabled): never a requirement.
const ALWAYS: &[&str] =
    &["", "core", "standard", "date", "spl", "pcre", "reflection", "json", "random", "hash", "uri"];

/// A function (or method): its parameters and return type as PHP reports them.
#[derive(Debug, Clone, Copy)]
pub struct Function {
    pub name: &'static str,
    pub params: &'static str,
    pub returns: &'static str,
    pub since: &'static str,
    /// The version it was removed in (`""`: still there).
    pub removed: &'static str,
    /// The extension providing it (`core`, `redis`…).
    pub ext: &'static str,
}

impl Function {
    /// `(string $haystack, string $needle): bool`.
    pub fn signature(&self) -> String {
        if self.returns.is_empty() {
            format!("({})", self.params)
        } else {
            format!("({}): {}", self.params, self.returns)
        }
    }
}

/// A class, interface, trait or enum.
#[derive(Debug, Clone, Copy)]
pub struct Class {
    /// The full name, as PHP writes it (`http\Env\Request`).
    pub name: &'static str,
    pub kind: &'static str,
    pub since: &'static str,
    pub removed: &'static str,
    pub ext: &'static str,
    /// The class it extends (`""`: none) and the interfaces it implements, comma-separated.
    pub parent: &'static str,
    pub interfaces: &'static str,
}

/// A property a built-in class declares.
#[derive(Debug, Clone, Copy)]
pub struct Property {
    pub name: &'static str,
    pub modifiers: &'static str,
    /// Its type, as PHP writes it (`""`: none).
    pub ty: &'static str,
}

impl Property {
    pub fn is_static(&self) -> bool {
        self.modifiers.split(' ').any(|m| m == "static")
    }

    /// Readable from outside the class.
    pub fn is_public(&self) -> bool {
        !self.modifiers.split(' ').any(|m| m == "protected" || m == "private")
    }
}

/// A method of a built-in class, as PHP reports it.
#[derive(Debug, Clone, Copy)]
pub struct Method {
    pub name: &'static str,
    /// `public static`, `abstract public`, `final protected`…
    pub modifiers: &'static str,
    pub params: &'static str,
    pub returns: &'static str,
    pub since: &'static str,
    pub removed: &'static str,
}

impl Method {
    pub fn is_static(&self) -> bool {
        self.modifiers.split(' ').any(|m| m == "static")
    }

    /// Callable from outside the class (not `protected` nor `private`).
    pub fn is_public(&self) -> bool {
        !self.modifiers.split(' ').any(|m| m == "protected" || m == "private")
    }

    /// `(string $format): string`.
    pub fn signature(&self) -> String {
        if self.returns.is_empty() {
            format!("({})", self.params)
        } else {
            format!("({}): {}", self.params, self.returns)
        }
    }
}

impl Class {
    /// The types it extends and implements, as PHP writes them.
    pub fn ancestors(&self) -> impl Iterator<Item = &'static str> {
        std::iter::once(self.parent)
            .chain(self.interfaces.split(','))
            .filter(|name| !name.is_empty())
    }

    /// The name without its namespace.
    pub fn short(&self) -> &'static str {
        self.name.rsplit('\\').next().unwrap_or(self.name)
    }
}

#[derive(Debug, Default)]
pub struct Stubs {
    /// The versions the data was generated from, oldest first.
    pub versions: Vec<&'static str>,
    /// Lowercase name → function (in name order: `sorted` below).
    functions: HashMap<String, Function>,
    sorted: Vec<&'static str>,
    classes: HashMap<String, Class>,
    /// The classes, by name (for completion).
    class_list: Vec<Class>,
    /// Name → (since, removed).
    constants: HashMap<&'static str, (&'static str, &'static str)>,
    /// A class's lowercase name → its own methods (not the inherited ones).
    methods: HashMap<String, Vec<Method>>,
    /// A class's lowercase name → its constants (with the inherited ones, as PHP lists them).
    class_constants: HashMap<String, Vec<&'static str>>,
    /// A class's lowercase name → the properties it declares.
    properties: HashMap<String, Vec<Property>>,
    /// A deprecated function's (`name`) or method's (`class::name`) lowercase name → the
    /// version deprecating it.
    deprecated: HashMap<String, &'static str>,
}

impl Stubs {
    /// The heap it takes (its text is the binary's: only the tables and the lowercase keys).
    pub fn weight(&self) -> u64 {
        use kernel::memory::{map_bytes, vec_bytes};
        fn keys<V>(map: &HashMap<String, V>) -> u64 {
            map.keys().map(|k| k.capacity() as u64).sum()
        }
        vec_bytes(&self.versions)
            + map_bytes(&self.functions)
            + keys(&self.functions)
            + vec_bytes(&self.sorted)
            + map_bytes(&self.classes)
            + keys(&self.classes)
            + vec_bytes(&self.class_list)
            + map_bytes(&self.constants)
            + map_bytes(&self.methods)
            + keys(&self.methods)
            + self.methods.values().map(vec_bytes).sum::<u64>()
            + map_bytes(&self.class_constants)
            + keys(&self.class_constants)
            + self.class_constants.values().map(vec_bytes).sum::<u64>()
            + map_bytes(&self.properties)
            + keys(&self.properties)
            + self.properties.values().map(vec_bytes).sum::<u64>()
            + map_bytes(&self.deprecated)
            + keys(&self.deprecated)
    }
}

/// The stubs: read on first use, let go when unused for a while (the module's
/// `release_idle`), read again when needed.
pub static STUBS: kernel::cache::OnDemand<Stubs> = kernel::cache::OnDemand::new(|| parse(DATA));

pub fn get() -> std::sync::Arc<Stubs> {
    STUBS.get()
}

pub(crate) fn parse(data: &'static str) -> Stubs {
    let mut stubs = Stubs::default();
    for line in data.lines() {
        if line.starts_with('#') {
            continue;
        }
        if let Some(versions) = line.strip_prefix("v\t") {
            stubs.versions = versions.split(',').collect();
            continue;
        }
        let mut f = line.split('\t');
        let (Some(since), Some(removed), Some(kind)) = (f.next(), f.next(), f.next()) else {
            continue;
        };
        match kind {
            "f" => {
                let (Some(name), params, returns) = (f.next(), f.next(), f.next()) else {
                    continue;
                };
                let function = Function {
                    name,
                    params: params.unwrap_or(""),
                    returns: returns.unwrap_or(""),
                    since,
                    removed,
                    ext: f.next().unwrap_or("core"),
                };
                stubs.functions.insert(name.to_ascii_lowercase(), function);
                stubs.sorted.push(name);
            }
            "c" => {
                let (Some(kind), Some(name)) = (f.next(), f.next()) else { continue };
                // The parent and interfaces, then the extension.
                let parent = f.next().unwrap_or("");
                let interfaces = f.next().unwrap_or("");
                let ext = f.next().unwrap_or("core");
                let class = Class { name, kind, since, removed, ext, parent, interfaces };
                stubs.classes.insert(name.to_ascii_lowercase(), class);
                stubs.class_list.push(class);
            }
            "m" => {
                let (Some(class), Some(name), Some(modifiers)) = (f.next(), f.next(), f.next())
                else {
                    continue;
                };
                let (params, returns) = (f.next().unwrap_or(""), f.next().unwrap_or(""));
                let method = Method { name, modifiers, params, returns, since, removed };
                stubs.methods.entry(class.to_ascii_lowercase()).or_default().push(method);
            }
            "cc" => {
                if let (Some(class), Some(name)) = (f.next(), f.next()) {
                    stubs.class_constants.entry(class.to_ascii_lowercase()).or_default().push(name);
                }
            }
            "p" => {
                if let (Some(class), Some(name)) = (f.next(), f.next()) {
                    let (modifiers, ty) = (f.next().unwrap_or(""), f.next().unwrap_or(""));
                    let property = Property { name, modifiers, ty };
                    stubs.properties.entry(class.to_ascii_lowercase()).or_default().push(property);
                }
            }
            "df" => {
                if let Some(name) = f.next() {
                    stubs.deprecated.insert(name.to_ascii_lowercase(), since);
                }
            }
            "dm" => {
                if let (Some(class), Some(name)) = (f.next(), f.next()) {
                    stubs.deprecated.insert(format!("{class}::{name}").to_ascii_lowercase(), since);
                }
            }
            "k" => {
                if let Some(name) = f.next() {
                    stubs.constants.insert(name, (since, removed));
                }
            }
            _ => {}
        }
    }
    stubs.sorted.sort_unstable();
    stubs
}

impl Stubs {
    pub fn function(&self, name: &str) -> Option<&Function> {
        self.functions.get(&name.trim_start_matches('\\').to_ascii_lowercase())
    }

    pub fn class(&self, name: &str) -> Option<&Class> {
        self.classes.get(&name.trim_start_matches('\\').to_ascii_lowercase())
    }

    /// The methods class `name` declares itself (not the inherited ones).
    pub fn methods(&self, class: &str) -> &[Method] {
        let key = class.trim_start_matches('\\').to_ascii_lowercase();
        self.methods.get(&key).map_or(&[], Vec::as_slice)
    }

    /// The constants of class `name` (the inherited ones too).
    pub fn class_constants(&self, class: &str) -> &[&'static str] {
        let key = class.trim_start_matches('\\').to_ascii_lowercase();
        self.class_constants.get(&key).map_or(&[], Vec::as_slice)
    }

    /// The properties class `name` declares itself.
    pub fn properties(&self, class: &str) -> &[Property] {
        let key = class.trim_start_matches('\\').to_ascii_lowercase();
        self.properties.get(&key).map_or(&[], Vec::as_slice)
    }

    /// The version deprecating a function (`name`) or a method (`Class::name`), if any.
    pub fn deprecated(&self, name: &str) -> Option<&'static str> {
        self.deprecated.get(&name.trim_start_matches('\\').to_ascii_lowercase()).copied()
    }

    pub fn constant(&self, name: &str) -> Option<(&'static str, &'static str)> {
        self.constants.get(name).copied()
    }

    /// The classes whose short name starts with `prefix` (case-insensitive).
    pub fn classes_with_prefix<'a>(&'a self, prefix: &'a str) -> impl Iterator<Item = &'a Class> {
        let prefix = prefix.to_ascii_lowercase();
        self.class_list.iter().filter(move |c| c.short().to_ascii_lowercase().starts_with(&prefix))
    }

    /// The extension providing a function or class, when it isn't one PHP always has (its
    /// core, `standard`, `date`, `spl`, `pcre`… can't be left out of a build).
    pub fn extension(&self, name: &str) -> Option<&'static str> {
        let ext = self.function(name).map(|f| f.ext).or_else(|| self.class(name).map(|c| c.ext))?;
        (!ALWAYS.contains(&ext)).then_some(ext)
    }

    /// The functions whose name starts with `prefix` (case-insensitive), in name order.
    pub fn functions_with_prefix<'a>(
        &'a self,
        prefix: &'a str,
    ) -> impl Iterator<Item = &'a Function> {
        let prefix = prefix.to_ascii_lowercase();
        self.sorted
            .iter()
            .filter(move |n| n.to_ascii_lowercase().starts_with(&prefix))
            .filter_map(|n| self.function(n))
    }

    /// The version a name (function, class or constant) appeared in, if after the oldest
    /// known one (older ones are always available).
    pub fn since(&self, name: &str) -> Option<&'static str> {
        let since = self
            .function(name)
            .map(|f| f.since)
            .or_else(|| self.class(name).map(|c| c.since))
            .or_else(|| self.constant(name).map(|(s, _)| s))?;
        (Some(&since) != self.versions.first()).then_some(since)
    }

    /// The version a name was removed in, if it was.
    pub fn removed(&self, name: &str) -> Option<&'static str> {
        let removed = self
            .function(name)
            .map(|f| f.removed)
            .or_else(|| self.class(name).map(|c| c.removed))
            .or_else(|| self.constant(name).map(|(_, r)| r))?;
        (!removed.is_empty()).then_some(removed)
    }
}

#[cfg(test)]
#[path = "../tests/unit/stubs.rs"]
mod tests;
